22	std::once_flag g_cupti_init_once;
23	CUptiResult g_cupti_init_status = CUPTI_SUCCESS;
24	
25	void write_error(char *error, size_t error_len, const std::string &message) {
26	    if (error == nullptr || error_len == 0) {
27	        return;
28	    }
29	    const size_t copy_len = std::min(error_len - 1, message.size());
30	    std::memcpy(error, message.data(), copy_len);
31	    error[copy_len] = '\0';
32	}
33	
34	std::string cupti_error(CUptiResult status, const char *call) {
35	    const char *name = nullptr;
36	    const char *description = nullptr;
37	    cuptiGetResultString(status, &name);
38	    cuptiGetResultString(status, &description);
39	    std::ostringstream out;
40	    out << call << " failed";
41	    if (name != nullptr) {
42	        out << ": " << name;
43	    }
44	    if (description != nullptr && description != name) {
45	        out << " (" << description << ")";
46	    }
47	    return out.str();
48	}
49	
50	std::string cuda_error(CUresult status, const char *call) {
51	    const char *name = nullptr;
52	    const char *description = nullptr;
53	    cuGetErrorName(status, &name);
54	    cuGetErrorString(status, &description);
55	    std::ostringstream out;
56	    out << call << " failed";
57	    if (name != nullptr) {
58	        out << ": " << name;
59	    }
60	    if (description != nullptr) {
61	        out << " (" << description << ")";
62	    }
63	    return out.str();
64	}
65	
66	void check_cupti(CUptiResult status, const char *call) {
67	    if (status != CUPTI_SUCCESS) {
68	        throw std::runtime_error(cupti_error(status, call));
69	    }
70	}
71	
72	void check_cuda(CUresult status, const char *call) {
73	    if (status != CUDA_SUCCESS) {
74	        throw std::runtime_error(cuda_error(status, call));
75	    }
76	}
