78	void initialize_cupti_once() {
79	    std::call_once(g_cupti_init_once, []() {
80	        CUpti_Profiler_Initialize_Params params = {
81	            CUpti_Profiler_Initialize_Params_STRUCT_SIZE
82	        };
83	        g_cupti_init_status = cuptiProfilerInitialize(&params);
84	    });
85	    check_cupti(g_cupti_init_status, "cuptiProfilerInitialize");
86	}
