88	struct CurrentContextGuard {
89	    CUcontext previous = nullptr;
90	
91	    explicit CurrentContextGuard(CUcontext context) {
92	        check_cuda(cuCtxGetCurrent(&previous), "cuCtxGetCurrent");
93	        check_cuda(cuCtxSetCurrent(context), "cuCtxSetCurrent");
94	    }
95	
96	    ~CurrentContextGuard() {
97	        cuCtxSetCurrent(previous);
98	    }
99	};
