101	struct HostObject {
102	    CUpti_Profiler_Host_Object *ptr = nullptr;
103	
104	    HostObject() = default;
105	    HostObject(const HostObject &) = delete;
106	    HostObject &operator=(const HostObject &) = delete;
107	
108	    HostObject(HostObject &&other) noexcept : ptr(std::exchange(other.ptr, nullptr)) {}
109	
110	    HostObject &operator=(HostObject &&other) noexcept {
111	        if (this != &other) {
