358	extern "C" int pegainfer_cupti_profile_range(
359	    CUcontext context, size_t device_index, const char *range_name,
360	    const char **metric_names, size_t metric_count, PegaCuptiCallback prepare_fn,
361	    PegaCuptiCallback launch_fn, void *userdata, double *metric_values,
362	    size_t metric_value_count, char *error, size_t error_len) {
363	    try {
364	        if (context == nullptr) {
365	            throw std::runtime_error("CUDA context is null");
366	        }
367	        if (range_name == nullptr) {
368	            throw std::runtime_error("range name is null");
369	        }
370	        if (metric_count == 0) {
371	            throw std::runtime_error("metric list is empty");
372	        }
373	        if (metric_names == nullptr || metric_values == nullptr) {
374	            throw std::runtime_error("metric input or output buffer is null");
375	        }
376	
377	        initialize_cupti_once();
378	        CurrentContextGuard current_context(context);
379	        const std::string chip = chip_name(device_index);
380	        const std::vector<uint8_t> availability = counter_availability_image(context);
381	        HostObject host = initialize_host(chip, availability);
382	        const std::vector<uint8_t> config =
383	            create_config_image(host.ptr, metric_names, metric_count);
384	        RangeObject range = enable_range_profiler(context);
385	        std::vector<uint8_t> counter_data =
386	            create_counter_data_image(range.ptr, metric_names, metric_count);
387	
388	        set_config(range.ptr, config, counter_data);
389	        profile_passes(range.ptr, range_name, prepare_fn, launch_fn, userdata);
390	        decode_data(range.ptr);
391	        evaluate(host.ptr, counter_data, metric_names, metric_count, metric_values,
392	                 metric_value_count);
393	        write_error(error, error_len, "");
394	        return 0;
395	    } catch (const std::exception &ex) {
396	        write_error(error, error_len, ex.what());
397	        return 1;
398	    } catch (...) {
399	        write_error(error, error_len, "unknown CUPTI profiler error");
400	        return 1;
401	    }
402	}
